{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_41",
      "quote": "If postnatal malnutrition influences long-­ term NCD risk as our results suggest, this is of global public health significance given the growing NCD epidemic in LMICs where there remains a large burden of severe childhood malnutrition. ... There is reasonable strength and consistency in the findings and biological plausibility to indicate an association between severe malnutrition or famine exposure and increased NCD risk. However, the precise mechanisms underlying this association remain largely unclear. For instance, how do long-­ term outcomes differ by duration, intensity, and age at which a child experiences malnutrition and what are the biological processes leading to long-­ term adverse effects.",
      "reason": "Text describes current evidence (strength, consistency, biological plausibility) and explicitly notes important uncertainties (mechanisms unclear; questions about duration, intensity, age)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_41",
      "quote": "If postnatal malnutrition influences long-­ term NCD risk as our results suggest, this is of global public health significance given the growing NCD epidemic in LMICs where there remains a large burden of severe childhood malnutrition. Prevention of severe malnutrition should be prioritised as no child should have to suffer the short-­ term or long-­ term effects of malnutrition. ... With over 80% of premature NCD-­ related deaths occurring in LMICs, where health systems already struggle with this massive disease burden, the need for interventions to prevent NCDs among severe malnutrition survivors is urgent. ... Recent predictions of major hunger following the COVID-19 pandemic make our review particularly timely.",
      "reason": "Text explains the public health importance and urgency of the review findings and why conducting the review is needed (global significance, policy/funding implications, timeliness)."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No retrieved evidence describing existing similar systematic reviews, nor explanation of the need for this review relative to prior reviews or citations of prior reviews."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_4",
      "quote": "Methods Our peer-­ reviewed search strategy focused on 'severe childhood malnutrition', 'LMICs', 'famine', and 'cardiometabolic NCDs' to identify studies in Medline, Embase, Global Health, and the Cumulative Index to Nursing and Allied Health Literature (CINAHL) databases.",
      "reason": "This review assesses exposures (severe childhood malnutrition/famine) and their long-term associations with NCDs, not effects of interventions; thus describing an intervention mechanism is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_4",
      "quote": "Methods Our peer-­ reviewed search strategy focused on 'severe childhood malnutrition', 'LMICs', 'famine', and 'cardiometabolic NCDs' to identify studies ...",
      "reason": "The review concerns exposure-outcome associations rather than evaluation of complex interventions or delivery contexts, so a logic model for intervention components is not applicable."
    }
  ],
  "confidence": "80"
}

