{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "Human studies published in English were assessed for eligibility against the following criteria: Population: older children and adults who survived an episode of documented severe malnutrition in LMICs or famine exposure in childhood and adolescence (defined as 0-18 years of age). ... Exposure: exposure definitions included two closely related groups: (1) documented severe malnutrition in childhood defined according to standard classifications based on low weight-for-height, low weight-for-age (WFA), low mid-upper arm circumference (MUAC), or nutritional oedema, or (2) famine conditions defined by severe food insecurity in the local area or country setting. ... Comparators: a comparison group unexposed to documented severe malnutrition or famine in childhood was preferred but not required. Outcomes: a range of cardiometabolic NCD outcomes (eg, impaired glucose metabolism, dyslipidaemia, hypertension) was considered if they were based on an objective clinical outcome measured at least 1 year after exposure to severe malnutrition or famine. All study designs were eligible.",
      "reason": "The chunk explicitly lists population (age and survivor status), exposure definitions, comparator preference, eligible outcomes with a minimum 1-year follow-up requirement, and states that all study designs were eligible."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_11",
      "quote": "Human studies published in English were assessed for eligibility against the following criteria: ... Grey literature and unpublished studies were excluded.",
      "reason": "The authors specify language (English) and publication status (excluded grey literature and unpublished studies) but do not report any dissemination year restriction; therefore report-characteristic eligibility is only partially specified."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No text in the provided evidence distinguishes exclusion because outcomes were not measured from exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_14",
      "quote": "Therefore, a narrative synthesis was carried out for each outcome with a focus on any differential effects of exposure between subgroups where data allowed (eg, sex-specific or age-specific differences). ... Data from studies of famine survivors and documented severe childhood malnutrition were analysed separately to account for the different nature of the exposures.",
      "reason": "The authors describe grouping studies for synthesis by outcome (narrative synthesis by outcome) and explicitly state that famine studies and documented severe childhood malnutrition studies were analysed separately, linking groups to the comparisons of different exposure types."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "Although severe stunting is a form of severe malnutrition, we excluded studies that considered stunted children alone as the association between stunting and increased NCD risk has been described elsewhere.",
      "reason": "A rationale is provided for the notable restriction excluding studies of stunting alone (because that association has been described elsewhere)."
    }
  ],
  "confidence": 85
}

